contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address account) public payable {
        require(account != address(0));

        uint256 cBalanceBefore = address(c).balance;
        uint256 accountBalanceBefore = c.balances(account); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 accountBalanceAfter = c.balances(account); if (__ESBMC_reverted()) return;
        uint256 cBalanceAfter = address(c).balance;

        assert(
            !reverted
            && accountBalanceAfter == 0
            && cBalanceAfter == cBalanceBefore
        );
    }

    receive() external payable {}
}

