pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address account) internal {
        vm.assume(account != address(0));
        uint256 cBalanceBefore = address(c).balance;
        uint256 accountBalanceBefore;
        try c.balances(account) returns (uint256 __r) { accountBalanceBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 accountBalanceAfter;
        try c.balances(account) returns (uint256 __r) { accountBalanceAfter = __r; } catch { return; }
        uint256 cBalanceAfter = address(c).balance;
        assertTrue(!reverted
            && accountBalanceAfter == 0
            && cBalanceAfter == cBalanceBefore);
    }

    function testFuzz_run(address account) public {
        vm.assume(account.code.length == 0 && uint160(account) > 0xffff && account != address(this) && account != address(c) && account != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && account != 0x000000000000000000636F6e736F6c652e6c6f67 && account != 0x4e59b44847b379578588920cA78FbF26c0B4956C && account != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(account);
    }

    receive() external payable {}
}
